```python
from copy import deepcopy
from math import isfinite


def compile_report(rows: list[dict], metric: str, limit: int) -> list[dict]:
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")
    if not isinstance(metric, str):
        raise TypeError("metric must be a string")
    if metric == "":
        raise ValueError("metric cannot be empty")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if limit < 0:
        raise ValueError("limit cannot be negative")

    seen = set()
    copied = []
    for row in rows:
        if not isinstance(row, dict):
            raise TypeError("each row must be a dictionary")
        if "key" not in row or metric not in row:
            raise ValueError("row is missing a required field")
        if not isinstance(row["key"], str):
            raise TypeError("key must be a string")
        if row["key"] in seen:
            raise ValueError("duplicate key")
        seen.add(row["key"])
        value = row[metric]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("metric values must be numeric")
        if not isfinite(value):
            raise ValueError("metric values must be finite")
        copied.append(deepcopy(row))

    copied.sort(key=lambda row: (row[metric], row["key"]))
    return copied[:limit]
```

